# typed: strict
# frozen_string_literal: true

require "parse_packwerk"
require "open3"

module GitHub
  module Packwerk
    module DomainIsolation
      class DomainIsolationViolationsTodos
        CROSS_DOMAIN_SQL_VIOLATION_COMMENT_PREFIX = "# domain-isolation-query-violation:ignore:"

        DOMAIN_ISOLATION_TODO_FILENAME = "domain_query_todo.yml"
        DOMAIN_ISOLATION_TODO_HEADER = <<-HEADER
# Note: this file is autogenerated. Run `bin/packwerk update-todo` to update this file.
# #
# # This file represents domain isolation violations, ignored with the `domain-isolation-query-violation:ignore:[package_name]` comment.
# # In order to ignore a domain isolation violation it must be annotated with that comment AND listed in this file.
# # Alternatively, violations can also be ignored via `domain_query_violations.yml` file if you don't care about the granularity and you're fine with ignoring violations per SQL query digest.
# #
# # To generate a list of all domain isolation violations, run: `script/domain-isolation-query-violations`.
# #
# # Domain isolation violations against this package are listed here so that CODEOWNERS will notify
# # the package's owning team of any changes to domain isolation violations.
#
        HEADER

        class ConsistencyError < StandardError; end

        sig { void }
        def self.check!
          new.check!
        end

        sig { void }
        def self.persist!
          new.persist!
        end

        sig { params(violations: T::Hash[String, T::Hash[String, T.untyped]]).void }
        def self.persist_inline_comments!(violations)
          new(packwerk_sql_violations: violations).persist_inline_comments!
        end

        sig { params(packwerk_sql_violations: T.nilable(T::Hash[String, T::Hash[String, T.untyped]])).void }
        def initialize(packwerk_sql_violations: nil)
          # violations defined in code as inline comments
          @domain_isolation_violations = T.let(nil, T.nilable(T::Hash[String, T::Hash[String, Integer]]))

          # violations generated by packwerk, coming from script/domain-isolation-query-violations
          @packwerk_sql_violations = T.let(packwerk_sql_violations, T.nilable(T::Hash[String, T::Hash[String, T.untyped]]))
        end

        sig { void }
        def persist_inline_comments!
          return unless @packwerk_sql_violations

          locations_to_packages = T.let({}, T::Hash[String, T::Set[String]])
          locations_to_query_types = T.let({}, T::Hash[String, T::Set[String]])

          @packwerk_sql_violations.each do |package_path, queries|
            queries.each do |_query_digest, query_meta|
              query_type = query_meta["query"].split(" ").first # e.g. SELECT, INSERT, UPDATE, DELETE

              query_meta["violations"].each do |violation|
                locations_to_packages[violation["location"]] ||= Set.new
                T.must(locations_to_packages[violation["location"]]) << package_path
                locations_to_query_types[violation["location"]] ||= Set.new
                T.must(locations_to_query_types[violation["location"]]) << query_type
              end
            end
          end

          locations_to_packages.each do |location, packages|
            file, line = location.split(":")
            line = line.to_i

            query_types = T.must(locations_to_query_types[location])

            # If there are multiple packages and query types, we just append them all to the comment
            comment = " #{CROSS_DOMAIN_SQL_VIOLATION_COMMENT_PREFIX}#{packages.join(", ")} (#{query_types.uniq.sort.join(", ")})"
            append_to_line(T.must(file), line, comment)
          end
        end

        sig { void }
        def check!
          ParsePackwerk.all.each do |package|
            filename = package.directory.join(DOMAIN_ISOLATION_TODO_FILENAME)

            raise_consistency_error(filename) if !filename.exist? &&  domain_isolation_todo_file_paths.include?(filename)
            raise_consistency_error(filename) if  filename.exist? && !domain_isolation_todo_file_paths.include?(filename)
          end

          domain_isolation_violations.each do |package_name, violations|
            package_dir = ParsePackwerk.find(package_name)&.directory
            next unless package_dir


            todo_filename = package_dir.join(DOMAIN_ISOLATION_TODO_FILENAME)
            text = File.read(todo_filename)

            raise_consistency_error(todo_filename) if text != todo_file_content(violations)
          end
        end

        sig { void }
        def persist!
          ParsePackwerk.all.each do |package|
            package.directory.join(DOMAIN_ISOLATION_TODO_FILENAME).delete if package.directory.join(DOMAIN_ISOLATION_TODO_FILENAME).exist?
          end

          domain_isolation_violations.each do |package_name, violations|
            package_dir = ParsePackwerk.find(package_name)&.directory
            next unless package_dir

            todo_filename = package_dir.join(DOMAIN_ISOLATION_TODO_FILENAME)
            todo_filename.write(todo_file_content(violations))
          end
        end

        sig { returns(T::Array[Pathname]) }
        def domain_isolation_todo_file_paths
          domain_isolation_violations.keys.map do |package_name|
            package_dir = ParsePackwerk.find(package_name)&.directory&.join(DOMAIN_ISOLATION_TODO_FILENAME)
          end.compact
        end

        sig { returns(T::Hash[String, T::Hash[String, Integer]]) }
        def domain_isolation_violations
          return @domain_isolation_violations if @domain_isolation_violations

          package_paths_to_filenames = {}

          out, _error, _status = Open3.capture3("grep --line-number --recursive --exclude-dir vendor --include *.rb --include *.erb '#{CROSS_DOMAIN_SQL_VIOLATION_COMMENT_PREFIX}'")
          out.each_line do |line|
            filename = line[/^(.+?):\d+/, 1]
            package_name = line[/#{CROSS_DOMAIN_SQL_VIOLATION_COMMENT_PREFIX}((\w|\/)+)/, 1]

            if package_name && filename
              package_paths_to_filenames[package_name] ||= {}
              package_paths_to_filenames[package_name][filename] ||= 0
              package_paths_to_filenames[package_name][filename] += 1
            end
          end

          @domain_isolation_violations = package_paths_to_filenames
        end

        private

        sig { params(filename: String, line_number: Integer, text_to_append: String).void }
        def append_to_line(filename, line_number, text_to_append)
          lines = File.readlines(filename)

          if line_number < 1 || line_number > lines.length
            raise ArgumentError, "Invalid line number. File has #{lines.length} lines."
          end

          text_to_append = " <%#{text_to_append.strip} %>" if filename.end_with?(".erb")

          # check if text_to_append is already there before appending:
          return if T.must(lines[line_number - 1]).include?(text_to_append)

          # Append the text to the specified line (convert to 0-indexed)
          lines[line_number - 1] = T.must(lines[line_number - 1]).chomp + text_to_append + "\n"

          File.write(filename, lines.join)
        end

        sig { params(violations: T::Hash[String, Integer]).returns(String) }
        def todo_file_content(violations)
          DOMAIN_ISOLATION_TODO_HEADER + violations.to_a.sort_by(&:first).to_h.to_yaml
        end

        sig { params(package_name: String).returns(Pathname) }
        def domain_isolation_todo_filepath(package_name)
          Pathname.new(
            File.join(package_name, DOMAIN_ISOLATION_TODO_FILENAME)
          ).cleanpath
        end

        sig { params(file_path: Pathname).void }
        def raise_consistency_error(file_path)
          raise ConsistencyError, "Discrepancy detected in #{file_path}. Run `bin/packwerk update` to fix."
        end
      end
    end
  end
end
